<template>
  <div class="row items-center no-wrap q-pa-md">
    <div class="col">
      {{ $t('allow_multiple_supplier_accounts_sync') }}
    </div>
    <div class="col-auto">
      <f-toggle size="xs"
        v-model="user_settings[ALLOW_MULTIPLE_SUPPLIER_ACCOUNTS_SYNC_SETTING]"
        :disable="loading"
        @update:model-value="
          (val) => {
            setMasterDataAllowMultiSupplierSetting(
              ALLOW_MULTIPLE_SUPPLIER_ACCOUNTS_SYNC_SETTING,
              val,
            );
          }
        "
      />
      <template v-if="setting_loading">
        <q-spinner-ios size="24px" color="primary" />
      </template>
    </div>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useSettingStore } from 'src/store/main';
import { ALLOW_MULTIPLE_SUPPLIER_ACCOUNTS_SYNC_SETTING } from 'src/constants';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
export default defineComponent({
  el: '#app',
    components: {},
  data() {
    return {
      ALLOW_MULTIPLE_SUPPLIER_ACCOUNTS_SYNC_SETTING,
    };
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        // data loading is done and value never set
        if (newVal == true && oldVal == false) {
          return;
        }
        this.initView();
      },
    },
  },
  mounted: function () {
    this.initView();
  },
  setup() {
    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const { updateSetting } = settings_store;

    return {
      setting_loading: ref(false),
      loading: ref(false),
      user_settings,
      loading_settings,
      updateSetting,
    };
  },
  methods: {
    initView() {
      if (
        !this.user_settings[this.ALLOW_MULTIPLE_SUPPLIER_ACCOUNTS_SYNC_SETTING]
      ) {
        this.user_settings[this.ALLOW_MULTIPLE_SUPPLIER_ACCOUNTS_SYNC_SETTING] =
          false;
      }
    },

    async setMasterDataAllowMultiSupplierSetting(key: string, value: any) {
      try {
        this.loading = true;
        this.setting_loading = true;
        await this.updateSetting(key, value);
        notify.success(this.$t('save_successfully'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
        this.setting_loading = false;
      }
    },
  },
});
</script>
