    <div class="width-300 q-pl-sm" id="left_section">
      <div
        class="full-width master-data-container page-height-100-135 thin-scrollbar master-data-list-container"
      >
        <div>
          <template
            v-for="(groups, key) in group_data_types"
            :key="key"
            :props="key"
          >
            <q-list padding>
              <q-expansion-item
                dense
                switch-toggle-side
                header-class="text-primary h-p-4"
                class="text-weight-bold"
              >
                <template v-slot:header>
                  <q-item-section>
                    <div class="display-flex">
                      <span>{{ $t(String(key)) }}</span>
                      <q-icon
                        name="settings"
                        class="q-ml-sm text-primary cursor-pointer"
                        size="22px"
                        @click.stop="showCustomMasterDataDlg()"
                        v-if="
                          String(key) == 'api_imported' &&
                          user_settings[custom_master_data]
                        "
                      />
                      <q-icon
