                      />
                    </div>
                  </q-item-section>
                </template>

                <q-item v-for="(type, index) in groups" :key="index">
                  <div
                    class="full-width display-flex cursor-pointer q-pa-sm text-weight-regular"
                    @click="selectTab(type, String(key))"
                  >
                    <!-- <q-icon size="18px" class="q-mr-sm" name="subdirectory_arrow_right" /> -->
                    <span class="text-capitalize q-pl-md">
                      {{ $t(aliases[type] || type) }}</span
                    >
                  </div>
                </q-item>
              </q-expansion-item>
            </q-list>
          </template>
        </div>
        <div
