        >
          {{ $t('settings') }}
          <q-icon name="settings" class="q-ml-sm" size="22px" />
        </div>
      </div>
    </div>
    <div class="width-100-300 q-pl-md" id="right_section">
      <q-btn
        id="menu_btn"
        round
