          outside-arrows
          mobile-arrows
          inline-label
        >
          <draggable
            :list="tabs"
            class="dragArea row"
            :group="{ name: 'master-data', pull: false, put: true }"
            :sort="true"
            item-key="name"
          >
            <template v-for="(element, index) in tabs" :key="index">
