<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import cache from 'src/utils/cache';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { masterDataApiService } from 'src/services';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import { custom_master_data } from 'src/constants';
import { VueDraggableNext } from 'vue-draggable-next';
import { getUserBasedKey } from 'src/utils/cacheHelper';
import { useMasterDataLookupStore, useSettingStore } from 'src/store/main';
import UploadCsv from 'src/pages/Settings/Components/MasterDataLookup/CustomMasterData/UploadCsv.vue';
import MasterDataTypeList from 'src/pages/Settings/Components/MasterDataLookup/MasterDataTypeList.vue';
import CustomMasterDataPopUp from 'src/pages/Settings/Components/MasterDataLookup/CustomMasterData/listPopUp.vue';
import MasterDataSettings from 'src/pages/Settings/Components/MasterDataLookup/MasterDataSettings.vue';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin, cache],
  props: {},
  components: {
    UploadCsv,
    MasterDataTypeList,
    MasterDataSettings,
    CustomMasterDataPopUp,
    draggable: VueDraggableNext,
  },
  data() {
    return {
      custom_master_data,
      masterDataTabsKey: 'master_data_tabs',
    };
  },
  beforeRouteLeave: function (to: any, from: any, next: any) {
    const master_data_lookup_store = useMasterDataLookupStore();
    master_data_lookup_store.$reset();
    next();
  },

  mounted: function () {
    this.initView();
    document.addEventListener(
      'fetch_data_set_types',
      this.getDataSetTypesWrapper,
    );
  },
  unmounted: function () {
    document.removeEventListener(
      'fetch_data_set_types',
      this.getDataSetTypesWrapper,
    );
  },
  methods: {
    async initView() {
      try {
        // this.loading = true;
        await this.getDataSetTypes();
        await this.getDataSetAliases();
        await this.startSettingsFetch();
        await this.getMasterDataList('record');

        // open old tabs. if no old tab then open first one
        this.openDefaultTabs();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        // this.loading = false;
      }
    },
    selectTab(type: string, parentTab: string) {
      this.selectedTab = type;
      const isFound = this.tabs.findIndex((item: any) => item.type === type);

      // if not already added then add it
      if (isFound == -1) {
        this.tabs.push({ type: type, parentTab: parentTab });
        this.setDataToLocalStorage(
          getUserBasedKey(this.masterDataTabsKey),
          JSON.stringify(this.tabs),
        );
      }
    },
    closeTab(index: any) {
      const closedTab = this.tabs[index];
      this.tabs.splice(index, 1);

      if (this.tabs.length == 0) {
        this.selectedTab = '';
        this.removeDataFromLocalStorage(
          getUserBasedKey(this.masterDataTabsKey),
        );
        return;
      }

      if (closedTab.type === this.selectedTab) {
        // If the closed tab is active, switch to another tab
        const lastIndex = this.tabs.length - 1;
        this.selectedTab = this.tabs[lastIndex].type;
        this.setDataToLocalStorage(
          getUserBasedKey(this.masterDataTabsKey),
          JSON.stringify(this.tabs),
        );
      }
    },
    async getDataSetTypes() {
      try {
        this.group_data_types = [] as any;
        const response = await masterDataApiService.getGroupedDataSetTypes();
        if (response.success != true) {
          throw { message: response.message };
        }

        this.group_data_types = response.data;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    getDataSetTypesWrapper(e: any) {
      this.getDataSetTypes();
    },
    showCustomMasterDataDlg() {
      this.show_custom_master_data = !this.show_custom_master_data;
    },
    showUploadCSVDlg() {
      this.show_upload_csv = !this.show_upload_csv;
    },
    openDefaultTabs() {
      // check for saved tabs;
      const lastOpenedTabs = this.getDataByKey(
        getUserBasedKey(this.masterDataTabsKey),
      );

      if (lastOpenedTabs) {
        this.tabs = JSON.parse(lastOpenedTabs as string);
      } else {
        // open first tabe for forst group
        for (const [key, item] of Object.entries(this.group_data_types)) {
          const groups = item as any;

          if (groups && groups.length > 0) {
            this.tabs.push({ type: groups[0], parentTab: key });
            this.setDataToLocalStorage(
              getUserBasedKey(this.masterDataTabsKey),
              JSON.stringify(this.tabs),
            );
            break;
          }
        }
      }

      if (!this.tabs || this.tabs.length == 0) {
        return;
      }

      this.selectedTab = this.tabs[0].type;
    },
  },
  setup() {
    const master_data_lookup_store = useMasterDataLookupStore();
    const { getDataSetAliases, getMasterDataList } = master_data_lookup_store;
    const { aliases } = storeToRefs(master_data_lookup_store);

    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);
    const { startSettingsFetch } = settings_store;
    return {
      user_settings,
      getDataSetAliases,
      getMasterDataList,
      startSettingsFetch,
      aliases,
      loading: ref(false),
      show_upload_csv: ref(false),
      group_data_types: ref([] as any),
      show_custom_master_data: ref(false),
      tabs: ref([] as any),
      selectedTab: ref(''),
    };
  },
});
</script>

