<template>
  <div class="master-data-settings">
    <DocbitsAccordionPanel
      v-model="expandedSections.supplierBod"
      icon="mdi:database-import"
      :title="$t('settings_masterdata_supplier_bod')"
      bodyClass="settings-card"
    >
      <MasterDataSupplierSetting />
    </DocbitsAccordionPanel>

    <DocbitsAccordionPanel
      v-model="expandedSections.poRetention"
      icon="mdi:delete-clock"
      :title="$t('purchase_order_deletion') + ' ' + $t('assistant')"
      bodyClass="settings-card"
    >
      <div class="row items-center no-wrap q-pa-md">
        <div class="col">
          <span>{{ $t('po_retention_period') }}</span>
          <q-icon name="info" class="q-ml-sm text-primary" size="22px">
            <q-tooltip>
              {{ $t('po_retention_period_tooltip') }}
            </q-tooltip>
          </q-icon>
        </div>
        <div class="col-auto" style="min-width: 200px;">
          <q-select
            outlined
            dense
            emit-value
            map-options
            v-model="selected_po_retention_period_value"
            @update:model-value="
              saveSetting(
                selected_po_retention_period,
                selected_po_retention_period_value,
              )
            "
            :options="po_retention_period"
            :option-label="getOptionLabel"
          />
        </div>
      </div>
    </DocbitsAccordionPanel>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import { po_retention_period, CONSTANTS } from 'src/constants';
import { useSettingStore } from 'src/store/main';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import MasterDataSupplierSetting from 'pages/Settings/Components/Modules/master-data-settings-supplier.vue';
import DocbitsAccordionPanel from 'src/single-component/DocbitsAccordionPanel.vue';
export default defineComponent({
  components: { MasterDataSupplierSetting, DocbitsAccordionPanel },
    data() {
    const settings_store = useSettingStore();
    const { getSetting, getOrgSettings, updateSetting } = settings_store;
    return {
      expandedSections: {
        supplierBod: true,
        poRetention: true,
      } as Record<string, boolean>,
      selected_po_retention_period: CONSTANTS.selected_po_retention_period,
      selected_po_retention_period_value: ref(po_retention_period[1]),
      po_retention_period,
      getSetting,
      getOrgSettings,
      updateSetting,
    };
  },
  mounted: function () {
    this.initView();
  },
  methods: {
    async initView() {
      this.selected_po_retention_period_value = await this.getSetting(
        this.selected_po_retention_period,
      );
    },
    async saveSetting(key: string, value: any) {
      await this.updateSetting(key, value);
      try {
        await this.updateSetting(key, value);
        notify.success(this.$t('MSG_SAVE'));
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },

    getOptionLabel(option: any) {
      return this.$t(`${option.label}`);
    },
  },
});
</script>

